Adviento.reducido=matchMedia('(prefers-reduced-motion: reduce)').matches;Adviento.festejar=(dia)=>{if(Adviento.reducido)return;if(typeof confetti==='function')confetti({particleCount:dia===24?160:65,spread:100,origin:{y:.65},colors:dia===18?['#e4007c','#784599','#ffd166']:['#ff7a00','#ffd166','#fff3e0']});else{for(let i=0;i<20;i++)Adviento.particula(['✿','✦','♥'][i%3])}};Adviento.particula=(char)=>{if(Adviento.reducido||document.hidden)return;const e=document.createElement('span');e.className='particle';e.textContent=char;e.style.left=Math.random()*100+'vw';e.style.animationDuration=(4+Math.random()*5)+'s';document.getElementById('particles').append(e);setTimeout(()=>e.remove(),10000)};
/* Mariposas ligeras en el retablo; se omiten si se prefiere menos movimiento. */
Adviento.iniciarAmbiente=()=>{if(Adviento.reducido)return;const hero=document.querySelector('.hero-art');if(!hero)return;const total=matchMedia('(max-width: 767px)').matches?2:4;for(let i=0;i<total;i++){const e=document.createElement('span');e.className='butterfly';e.setAttribute('aria-hidden','true');e.textContent='🦋';e.style.left=(12+i*22)+'%';e.style.top=(25+(i%2)*38)+'%';e.style.animationDelay=(-i*1.2)+'s';hero.append(e)}document.addEventListener('visibilitychange',()=>{hero.querySelectorAll('.butterfly').forEach(e=>e.style.animationPlayState=document.hidden?'paused':'running')})};
